import { WordGameItemSource } from "./WordGameItemSource";

function symbolContent(character: string, audioUrl?: string): GameItemContent {
	return {
		kind: "symbol",
		symbolCharacter: character,
		promptText: character,
		correctAnswer: `name of ${character}`,
		audioUrl,
