}

function vocabEntry(thai: string, audioUrl?: string): VocabEntry {
	return {
		thai,
		romanization: thai,
		word_class: "noun",
		english: `meaning of ${thai}`,
		rank: null,
		frequency: 0,
		mnemonic: null,
		characters: [...thai],
		syllables: [],
		toneRules: [],
		thai_audio_file: audioUrl ?? null,
		english_audio_file: null,
		image_file: null,
		samples: [],
		source: "test",
	};
}

function vocabCard(
	id: string,
	promptWord: string,
	property: string,
): VocabCard {
	return new VocabCard(
		id,
		"question",
		"answer",
		["answer"],
		SrsSchedule.initial(),
		promptWord,
		property,
	);
}

function repositoryOf(
	scriptCards: readonly ScriptPropertyCard[],
	vocabCards: readonly VocabCard[],
): CardRepository {
	return {
		findById: () => null,
		findDue: () => [],
		findAll: (pool: CardPool) => {
			if (pool === "script") return [...scriptCards];
			if (pool === "vocab") return [...vocabCards];
			return [];
		},
		save: () => {},
		saveAll: () => {},
		remove: () => {},
	};
}

