				["word", "production"],
				["word", "dictationTranslate"],
			]);
		});

		it("never assigns dictationTranslate to a word with no audio", () => {
			const service = new GameItemSelectionService([
				sourceOf("vocab", [wordContent("silent"), wordContent("loud", "/a.mp3")]),
